import { TOWER_TABLE } from "../constants";
/**
 * Returns the exact GFDSS strategy instruction based on current seed and magic states.
 */
export function getGFDSSInstruction(state) {
    const levelIndex = Math.min(Math.max(state.towerLevel - 1, 0), 9);
    const data = TOWER_TABLE[levelIndex];
    const spell = state.nextSpellName;
    const rs = state.gfdRandomSeed;
    const nextRs = state.nextGfdRandomSeed; // <-- НОВАЯ ПЕРЕМЕННАЯ ДЛЯ 2a и 2b
    // Helper to format the base "x" cast, applying Supreme Intellect if it's a teal cell
    const castXStr = data.tealX
        ? `Slot Supreme Intellect, cast GFD with ${data.x} towers (unslot SI afterwards unless instructed otherwise)`
        : `Cast GFD with ${data.x} towers`;
    // --------------------------------------------------------
    // STEP 3: Fallback Function
    // --------------------------------------------------------
    const getStep3 = () => {
        const rbString = state.towerLevel === 8 ? " (And Reality Bending)" : "";
        const reloadStr = state.isWebPlayer
            ? "Save using Ctrl + S, then immediately reload browser"
            : "Immediately export save, then import save";
        return `STEP 3: Wait for exactly 28 magic. Have minimum towers. Slot Supreme Intellect${rbString}. Cast GFD. Before it resolves: ${reloadStr}.`;
    };
    // Helper to validate if required variables exist (aren't null in table)
    const validateVars = (...vars) => {
        return vars.every((v) => v !== null);
    };
    // --------------------------------------------------------
    // STEP 2: Initial Spell Routing
    // --------------------------------------------------------
    if (spell === "ST" || spell === "RA") {
        return `STEP 2: ${castXStr} and let resolve.`;
    }
    if (["CBG", "FtHoF", "HC", "SCP"].includes(spell)) {
        return `STEP 2: Cast GFD with ${data.y} towers and let resolve.`;
    }
    // --------------------------------------------------------
    // STEP 2a: Next cast is Diminish Ineptitude (DI)
    // --------------------------------------------------------
    if (spell === "DI") {
        let instruction;
        // ИСПОЛЬЗУЕМ nextRs ДЛЯ ВСЕХ ПРОВЕРОК ЗДЕСЬ
        if (nextRs <= 0.33333 && validateVars(data.e1, data.n1)) {
            instruction = `Cast GFD with ${data.e1} towers, sell to ${data.n1} towers, and cast GFD again within 1s.`;
        }
        else if (nextRs > 0.33333 &&
            nextRs < 0.4 &&
            validateVars(data.e1, data.n2)) {
            instruction = `Cast GFD with ${data.e1} towers, sell to ${data.n2} towers, and cast GFD again within 1s.`;
        }
        else if (nextRs >= 0.4 &&
            nextRs < 0.42857 &&
            validateVars(data.e2, data.n4)) {
            instruction = `Cast GFD with ${data.e2} towers, sell to ${data.n4} towers, and cast GFD again within 1s.`;
            if (state.towerLevel === 3 || state.towerLevel === 4) {
                instruction +=
                    " (After first resolve but before second, buy at least 100 Wizard Towers).";
            }
        }
        else if (nextRs >= 0.66667 &&
            nextRs < 0.83333 &&
            validateVars(data.e3, data.n3)) {
            instruction = `Cast GFD with ${data.e3} towers, sell to ${data.n3} towers, and cast GFD again within 1s.`;
        }
        else if (nextRs >= 0.83333 &&
            nextRs < 0.85714 &&
            validateVars(data.e2, data.n4)) {
            instruction = `Cast GFD with ${data.e2} towers, sell to ${data.n4} towers, and cast GFD again within 1s.`;
            if (state.towerLevel === 3 || state.towerLevel === 4) {
                instruction +=
                    " (After first resolve but before second, buy at least 100 Wizard Towers).";
            }
        }
        else {
            return getStep3();
        }
        return `STEP 2a: ${instruction}`;
    }
    // --------------------------------------------------------
    // STEP 2 & 2b: Next cast is Spontaneous Edifice (SE)
    // --------------------------------------------------------
    if (spell === "SE") {
        // Step 2 preliminary checks (ИСПОЛЬЗУЕТСЯ ТЕКУЩИЙ rs, так как условие относится к текущему SE)
        if (rs >= 0.375 && rs < 0.42857 && validateVars(data.z)) {
            return `STEP 2: Cast GFD with ${data.z} towers and let resolve.`;
        }
        if (state.canAffordS && validateVars(data.s)) {
            return `STEP 2: Cast GFD with ${data.s} towers and let resolve.`;
        }
        // Proceed to Step 2b (ИСПОЛЬЗУЕМ nextRs)
        let instruction;
        if (nextRs >= 0 && nextRs < 0.5) {
            instruction = `${castXStr}, and before resolving, buy at least 400 Wizard towers.`;
        }
        else if (nextRs >= 0.5 && nextRs < 0.6 && validateVars(data.y)) {
            instruction = `Slot Supreme Intellect (if not already), cast GFD with ${data.x} towers, then within 1s buy to ${data.y} towers and cast GFD. Afterwards, unslot SI.`;
        }
        else if (nextRs >= 0.6 && nextRs < 0.71428 && validateVars(data.c)) {
            instruction = `${castXStr}, then within 1s buy to ${data.c} towers and cast GFD.`;
        }
        else if (nextRs >= 0.71428 && nextRs < 0.85714) {
            instruction = `${castXStr}, twice in quick succession (within 1s).`;
        }
        else if (nextRs >= 0.85714 && nextRs < 0.875) {
            if (state.towerLevel < 6) {
                instruction = `Cast GFD with ${data.x} towers, slot SI, cast GFD again. Afterwards, unslot SI.`;
            }
            else {
                return getStep3();
            }
        }
        else if (nextRs >= 0.875) {
            const reloadStr = state.isWebPlayer
                ? "save and reload (Ctrl+S -> Reload)"
                : "save and reload (Export -> Import)";
            // ИСПОЛЬЗУЕМ nextGfdWillBackfire
            if (state.nextGfdWillBackfire) {
                if (!validateVars(data.d1))
                    return getStep3();
                instruction = `Have ${data.d1} towers and full magic. Cast GFD, slot SI, cast GFD again. After 1st resolves but before 2nd, ${reloadStr}. Afterwards, unslot SI.`;
            }
            else {
                if (!validateVars(data.d2))
                    return getStep3();
                instruction = `Have ${data.d2} towers and full magic. Cast GFD twice in quick succession, then buy >=400 Wizard towers (all within 1s). After 1st resolves but before 2nd, ${reloadStr}.`;
            }
        }
        else {
            return getStep3();
        }
        return `STEP 2b: ${instruction}`;
    }
    // Failsafe fallback
    return getStep3();
}
