import { getSkipState } from "./core/getSkipState";
import { getGFDSSInstruction } from "./core/getSkipInstruction";
import { replaceNativeHandlers } from "./handlers/replaceNativeHandlers";
const GFDSSHMod = {
    init: () => {
        replaceNativeHandlers();
        const grimoireUI = l("grimoireContent");
        const uiBlock = document.createElement("div");
        uiBlock.id = "SPSKBLock";
        uiBlock.style.marginTop = "10px";
        uiBlock.style.display = "flex";
        uiBlock.style.justifyContent = "center";
        uiBlock.style.gap = "5px";
        uiBlock.style.color = "rgba(255,255,255,0.75)";
        uiBlock.style.fontSize = "11px";
        if (grimoireUI)
            grimoireUI.appendChild(uiBlock);
        // 2. Вешаем хук на отрисовку кадра
        Game.registerHook("draw", () => {
            if (Game.drawT % 15 == 0) {
                const block = l("SPSKBLock");
                if (!block)
                    return;
                const wizardTower = Game.Objects["Wizard tower"];
                if (!wizardTower || !wizardTower.minigame)
                    return;
                const gfdState = getSkipState(Game.Objects["Wizard tower"]);
                const instruction = getGFDSSInstruction(gfdState);
                // 3. Вывод результата
                const isBackfireDisplay = gfdState?.nextGfdWillBackfire
                    ? "red"
                    : "green";
                block.innerHTML = `Next: <div class="${isBackfireDisplay}" style="margin: 0 4px;">${gfdState?.nextSpellName}</div> | RS: ${gfdState?.gfdRandomSeed.toFixed(5)} | Next RS: ${gfdState?.nextGfdRandomSeed.toFixed(5)} | Strat: ${instruction}`;
            }
        });
    },
};
if (!process.env.APP_NAME) {
    console.error("Failed to initialize the mod (app name missing)");
}
if (typeof Steam !== "undefined") {
    setTimeout(() => {
        Game.registerMod(process.env.APP_NAME, GFDSSHMod);
    }, 2000);
}
else {
    Game.registerMod(process.env.APP_NAME, GFDSSHMod);
}
